import{_ as o,o as a,c as t,a2 as c}from"./chunks/framework.CiKk3sJz.js";const p=JSON.parse('{"title":"漫画 · 第 1 话 选择器：样式的寻址系统","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.01-selectors.md","filePath":"comics/css/EP.01-selectors.md","lastUpdated":1792579602000}'),s={name:"comics/css/EP.01-selectors.md"};function r(d,e,l,i,n,h){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="漫画-·-第-1-话-选择器-样式的寻址系统" tabindex="-1">漫画 · 第 1 话 选择器：样式的寻址系统 <a class="header-anchor" href="#漫画-·-第-1-话-选择器-样式的寻址系统" aria-label="Permalink to &quot;漫画 · 第 1 话 选择器：样式的寻址系统&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/01-selectors">docs/css/01-selectors.md</a> ｜ 原画：<a href="./EP.01-selectors.svg">EP.01-selectors.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。按钮颜色不听话，让她第一次见识了优先级的&quot;隐形裁判&quot;。</li><li><strong>码叔</strong>：划重点担当，只在知识条出镜，负责带走三句结论。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>两条规则同时选中一个按钮，写在前面的 <code>#nav .btn</code> 竟然赢了写在后面的 <code>.toolbar .btn</code>。像素酱顺着&quot;谁说了算&quot;往下挖，挖出了优先级三元组 (A, B, C) 这套计分规则，也顺手捡到了 <code>:is()</code> / <code>:where()</code> / <code>:has()</code> 三件现代武器。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p><code>#nav .btn</code>（优先级 1, 1, 0）与 <code>.toolbar .btn</code>（优先级 0, 2, 0）抢同一个按钮。直觉上&quot;两个类更具体&quot;，但 <strong>ID 在 A 位，逐位比较时 1 &gt; 0 一票定胜负</strong>——类位堆到 99 也翻不了盘。这就是&quot;样式互相覆盖、只好堆 <code>!important</code>&quot;的根源：优先级失控时，逃生舱被当成了常规武器。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>优先级是一个三元组 <strong>(A, B, C)</strong>：A 数 ID，B 数类/属性/伪类，C 数元素/伪元素。比较规则是<strong>逐位比较</strong>，不是求和——<code>(1,0,0) &gt; (0,99,99)</code>。三个细节常被忽略：</p><ul><li><code>:not()</code> / <code>:is()</code> / <code>:has()</code> 本身不计分，但<strong>括号里最复杂的参数计入</strong>；</li><li><code>:where()</code> 无论括号里写了什么，<strong>恒为 0</strong>；</li><li>通配符 <code>*</code> 和组合器 <code>&gt;</code> <code>+</code> <code>~</code> 空格<strong>不产生任何优先级</strong>。</li></ul><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>现代逻辑伪类各司其职：</p><ul><li><code>:is(section, article) h1</code> —— 合并重复前缀，一条顶三条，优先级取参数最高值；</li><li><code>:where(img, video)</code> —— 零优先级，写&quot;默认层&quot;样式，业务一行类选择器就能覆盖；</li><li><code>.form-group:has(input:invalid)</code> —— <strong>父选择器</strong>登场：父级感知子级状态，表单组整体标红，过去必须 JS 加 class 的场景现在零 JS。</li></ul><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>优先级是 (A, B, C) 三元组，<strong>逐位比较</strong>，ID 一票定胜负。</li><li>要覆盖用 <code>:where</code>（优先级 0），要合并用 <code>:is</code>（取最高参数），父级联动用 <code>:has</code>。</li><li>浏览器<strong>从右往左</strong>匹配，关键选择器越短，引擎越省力——<code>ul li a span</code> 这种长链要避免。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>:is(#a, .b)</code> 和 <code>:where(#a, .b)</code> 的优先级分别是多少？</p><p><strong>答</strong>：前者取括号内最复杂参数，是 ID 级 (1, 0, 0)；后者恒为 (0, 0, 0)。所以&quot;想要默认样式随便被覆盖&quot;时，千万别把 <code>:is</code> 写成 <code>:where</code> 的替代品——口诀：<strong>要覆盖用 :where，要合并用 :is</strong>。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>属性/结构伪类交互速查：<a href="./../../examples/css/01-selectors/index-01-attribute-structural.html">examples/css/01-selectors/</a></li><li><code>:not</code> / <code>:is</code> / <code>:where</code> / <code>:has</code> 差异对比：<a href="./../../examples/css/01-selectors/index-02-logical-pseudo.html">index-02-logical-pseudo.html</a></li><li>优先级三元组实时演算：<a href="./../../examples/css/01-selectors/index-04-specificity-cascade.html">index-04-specificity-cascade.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>按钮 hover 想加个&quot;弹一下&quot;的手感，动画却把页面拖到掉帧——第 2 话《动画与过渡》，看看渲染流水线为什么只宠 <code>transform</code> 和 <code>opacity</code>。</p>',24)])])}const g=o(s,[["render",r]]);export{p as __pageData,g as default};
